import React, { Fragment, useEffect, useState } from 'react';
import { Row, Col, Checkbox, Typography, Card, Select, Skeleton } from 'antd';
import { connect } from 'react-redux';
import { useParams } from 'react-router-dom';

import { getSbsPlans, changePlan, changeAddonSuspendStatus } from '../Actions/SBS';

const { Title } = Typography;
const { Option } = Select;

function AutoDetectResidentialComponent(props) {
	const { addon_id } = useParams();
	const [suspend, setSuspend] = useState(false);

	useEffect(() => {
		if (!props.sbsPlans) {
			props.getSbsPlans(props.token);
		}

		props.installedAddons.forEach(ia =>
			ia.id === +addon_id ? setSuspend(ia.is_suspend) : null
		);

		// eslint-disable-next-line
	}, [props.addonSettings]);

	const changePlan = plan_value => {
		props.changePlan(props.token, plan_value);
	};

	if (!props.sbsPlans) {
		return <Skeleton active />;
	}

	let value = 'disable';

	if (
		+props?.sbsPlans?.current_plan?.status?.nextSubcribedPackage
			?.nextToBeChargedStatus === 1
	) {
		value = props.sbsPlans.current_plan.status.nextSubcribedPackage.nextSubscriptionSCAC;
	} else if (
		+props?.sbsPlans?.status?.nextSubcribedPackage?.nextToBeChargedStatus === 1
	) {
		value = props.sbsPlans.status.nextSubcribedPackage.nextSubscriptionSCAC;
	}

	const plan = props?.sbsPlans?.current_plan?.status ?? props?.sbsPlans?.status ?? null;

	return (
		<Fragment>
			<Row gutter={25}>
				<Col className='gutter-row mb-3' xs={24} sm={24} md={24} lg={24} xl={24}>
					<Title level={3} style={{ textAlign: 'center' }}>
						Small Package Box
					</Title>
				</Col>
			</Row>

			<Row gutter={30} justify='center' className={'mb-3'}>
				<Col className='gutter-row' xs={24} sm={24} md={24} lg={18} xl={12}>
					<Card style={{ width: '100%' }}>
						<p>
							The Box Sizes feature calculates the optimal packaging solution based on
							your standard box sizes. The solution is available graphically to assist
							order fulfillment. The next subscription begins when the current one expires
							or is depleted, which ever comes first. Refer to the User Guide for more
							detailed information.
						</p>

						<label>
							<strong>Auto-renew</strong>
						</label>
						<Select
							defaultValue={value}
							style={{ width: '100%', marginBottom: '20px' }}
							onChange={changePlan}
						>
							<Option key='disable' value='disable'>
								Disable (default)
							</Option>
							{props?.sbsPlans?.plans?.length > 0
								? props.sbsPlans.plans.map(plan => (
										<Option key={plan.pSCAC} value={plan.pSCAC}>{`${
											Number(plan.pHits)
												? new Intl.NumberFormat().format(plan.pHits)
												: plan.pHits
										}/mo ($${plan.pCost})`}</Option>
								  ))
								: props.sbsPlans?.ListOfPackages?.Info?.length > 0
								? props.sbsPlans.ListOfPackages.Info.map(plan => (
										<Option key={plan.pSCAC} value={plan.pSCAC}>{`${
											Number(plan.pHits)
												? new Intl.NumberFormat().format(plan.pHits)
												: plan.pHits
										}/mo ($${plan.pCost})`}</Option>
								  ))
								: null}
						</Select>

						{props?.sbsPlans?.current_plan === 'string' ? (
							<p>
								<strong>{props.sbsPlans.current_plan}</strong>
							</p>
						) : (
							<Fragment>
								{props?.sbsPlans?.current_plan === null ? (
									<h1 className='mb-2'>
										<b>No plan is activated.</b>
									</h1>
								) : (
									<Fragment>
										<label>
											<strong>Current plan</strong>
										</label>

										<div style={{ width: '100%', marginBottom: '20px' }}>
											<p style={{ marginBottom: '0' }}>
												${plan?.subscribedPackage?.packageCost}/
												{plan?.subscribedPackage?.packageDuration}
											</p>
											<p style={{ marginBottom: '0' }}>
												Start date:{' '}
												{new Date(plan?.subscriptionInfo?.subscriptionTime)
													.toDateString()
													.substring(4)}{' '}
											</p>
											<p style={{ marginBottom: '0' }}>
												End date:{' '}
												{new Date(plan?.subscriptionInfo?.expiryTime)
													.toDateString()
													.substring(4)}
											</p>
										</div>

										<label>
											<strong>Current usage</strong>
										</label>

										<div style={{ width: '100%', marginBottom: '20px' }}>
											<p style={{ marginBottom: '0' }}>
												{plan?.subscribedPackageHitsStatus?.consumedHits}/
												{plan?.subscribedPackageHitsStatus?.packageHits}{' '}
												{plan?.subscribedPackageHitsStatus?.consumedHitsPrcent}%{' '}
												{+plan?.lastUsageTime.replace(/[-: ]/g, '') === 0}
											</p>
										</div>
									</Fragment>
								)}
							</Fragment>
						)}

						<div style={{ width: '100%', marginBottom: '20px' }}>
							<Checkbox
								onChange={e => {
									setSuspend(e.target.checked);
									props.changeAddonSuspendStatus(addon_id, props.token);
								}}
								checked={suspend}
							>
								Suspend Use
							</Checkbox>
						</div>
					</Card>
				</Col>
			</Row>
		</Fragment>
	);
}

const mapStateToProps = state => {
	return {
		token: state.token,
		sbsPlans: state.sbsPlans,
		installedAddons: state.installedAddons,
		alertMessage: state.alertMessageType,
		addonSettings: state.addonSettings,
	};
};

const mapDispatchToProps = dispatch => {
	return {
		getSbsPlans: token => dispatch(getSbsPlans(token)),
		changePlan: (token, plan_package) => dispatch(changePlan(token, plan_package)),
		changeAddonSuspendStatus: (addon_id, token) =>
			dispatch(changeAddonSuspendStatus(addon_id, token)),
	};
};

export default connect(
	mapStateToProps,
	mapDispatchToProps
)(AutoDetectResidentialComponent);
